def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    row_lines = [r for r in range(h) if grid[r][0] != bg and all(x == grid[r][0] for x in grid[r])]
    col_lines = [c for c in range(w) if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))]

    out = [row[:] for row in grid]

    def replicate(lines, length, horizontal):
        bounds = [-1] + lines + [length]
        panels = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
        sizes = [b - a for a, b in panels]
        if not sizes or len(set(sizes)) != 1 or sizes[0] == 0:
            return False
        size = sizes[0]
        pattern = {}
        for start, end in panels:
            for offset in range(size):
                for cross in range(w if horizontal else h):
                    r, c = (start + offset, cross) if horizontal else (cross, start + offset)
                    if grid[r][c] != bg:
                        pattern[(offset, cross)] = grid[r][c]
        for start, end in panels:
            for (offset, cross), color in pattern.items():
                r, c = (start + offset, cross) if horizontal else (cross, start + offset)
                out[r][c] = color
        return True

    if row_lines:
        replicate(row_lines, h, True)
    elif col_lines:
        replicate(col_lines, w, False)
    return out
